<section class="page-heading compact"><div class="container"><div class="eyebrow">YOUR PRINT JOURNEY</div><h1>Orders in <em>motion.</em></h1><p>Follow the progress of your PrintPack orders.</p></div></section><section class="section-pad"><div class="container"><div class="orders-table-wrap"><table class="table align-middle"><thead><tr><th>Order</th><th>Vendor</th><th>Placed</th><th>Status</th><th>Total</th><th>Tracking</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong>#<?= (int)$o['id'] ?></strong></td><td><?= e($o['vendor_name']) ?></td><td><?= e(date('d M Y',strtotime($o['created_at']))) ?></td><td><span class="status-pill <?= e(status_class($o['status'])) ?>"><?= e(ucfirst($o['status'])) ?></span></td><td><?= money($o['total_amount']) ?></td><td><a target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=<?= urlencode($o['delivery_address']) ?>">Open map ↗</a></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="6" class="text-center py-5">No orders yet. <a href="<?= e(url('services')) ?>">Find your first service ↗</a></td></tr><?php endif; ?></tbody></table></div><p class="field-help mt-3">Map links open directions to the delivery address; live vehicle GPS tracking requires a driver location feed.</p></div></section>
